CREATE TRIGGER gwg_check_freeze_gwg_claim BEFORE UPDATE OF status, verified_at, destroyed_at, client_id ON public.gwg_check FOR EACH ROW WHEN (((old.status IS DISTINCT FROM new.status) OR (old.verified_at IS DISTINCT FROM new.verified_at) OR (old.destroyed_at IS DISTINCT FROM new.destroyed_at) OR (old.client_id IS DISTINCT FROM new.client_id))) EXECUTE FUNCTION app.freeze_gwg_claim_references();
